CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teams(id SERIAL PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS team_members(team_id INT REFERENCES teams ON DELETE CASCADE,user_id INT REFERENCES users ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('admin','member','viewer')),PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS boards(id SERIAL PRIMARY KEY,team_id INT REFERENCES teams ON DELETE CASCADE,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS columns(id SERIAL PRIMARY KEY,board_id INT REFERENCES boards ON DELETE CASCADE,title TEXT NOT NULL,position INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id SERIAL PRIMARY KEY,column_id INT REFERENCES columns ON DELETE CASCADE,title TEXT NOT NULL,description TEXT DEFAULT '',position INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
